// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Arrays;

import org.junit.jupiter.api.Test;

/** Value/snapshot contracts before and after allocation-only cost-data changes; no identity-cache requirements. */
class LmdbNativeCostDataOwnershipTest {

	@Test
	void aBuiltVectorIsIndependentOfLaterScalarAndVectorAdds() {
		var builder = LmdbNativeCostVector.builder()
				.add(LmdbNativeCostVector.Feature.OPEN, 1.0, 2.0, 3.0);
		var first = builder.build();
		int firstHash = first.hashCode();
		assertEquals(first, builder.build());
		builder.add(first);
		var second = builder.build();
		builder.add(LmdbNativeCostVector.Feature.OPEN, 4.0);
		var third = builder.build();
		assertBounds(first, LmdbNativeCostVector.Feature.OPEN, 1.0, 2.0, 3.0);
		assertBounds(second, LmdbNativeCostVector.Feature.OPEN, 2.0, 4.0, 6.0);
		assertBounds(third, LmdbNativeCostVector.Feature.OPEN, 6.0, 8.0, 10.0);
		assertEquals(firstHash, first.hashCode());
		assertEquals(LmdbNativeCostVector.bounds(LmdbNativeCostVector.Feature.OPEN, 1.0, 2.0, 3.0), first);
	}

	@Test
	void zeroSnapshotsDoNotShareMutableBuilderState() {
		var builder = LmdbNativeCostVector.builder();
		var zero = builder.build();
		builder.add(LmdbNativeCostVector.Feature.OPEN, -0.0);
		assertEquals(zero, builder.build());
		builder.add(LmdbNativeCostVector.Feature.OPEN, 1.0);
		assertTrue(zero.isZero());
		assertBounds(zero, LmdbNativeCostVector.Feature.OPEN, 0.0, 0.0, 0.0);
		assertBounds(builder.build(), LmdbNativeCostVector.Feature.OPEN, 1.0, 1.0, 1.0);
	}

	@Test
	void exportedArraysCannotMutateTheVectorOrItsBuilder() {
		var builder = LmdbNativeCostVector.builder().add(LmdbNativeCostVector.Feature.INDEX_SEEK, 2.0, 3.0, 4.0);
		var vector = builder.build();
		Arrays.fill(vector.lowArray(), 70.0);
		Arrays.fill(vector.expectedArray(), 80.0);
		Arrays.fill(vector.highArray(), 90.0);
		assertBounds(vector, LmdbNativeCostVector.Feature.INDEX_SEEK, 2.0, 3.0, 4.0);
		assertEquals(vector, builder.build());
		builder.add(LmdbNativeCostVector.Feature.INDEX_SEEK, 1.0);
		assertBounds(vector, LmdbNativeCostVector.Feature.INDEX_SEEK, 2.0, 3.0, 4.0);
		assertBounds(builder.build(), LmdbNativeCostVector.Feature.INDEX_SEEK, 3.0, 4.0, 5.0);
	}

	@Test
	void rejectedMutationsLeaveEarlierAndFutureSnapshotsIntact() {
		var builder = LmdbNativeCostVector.builder().add(LmdbNativeCostVector.Feature.OPEN, Double.MAX_VALUE);
		var first = builder.build();
		assertThrows(NullPointerException.class, () -> builder.add((LmdbNativeCostVector) null));
		assertThrows(NullPointerException.class, () -> builder.add(null, 1.0));
		assertThrows(IllegalArgumentException.class,
				() -> builder.add(LmdbNativeCostVector.Feature.OPEN, Double.NaN));
		assertEquals(first, builder.build());
		builder.add(first);
		assertBounds(builder.build(), LmdbNativeCostVector.Feature.OPEN, Double.MAX_VALUE, Double.MAX_VALUE,
				Double.POSITIVE_INFINITY);
		assertBounds(first, LmdbNativeCostVector.Feature.OPEN, Double.MAX_VALUE, Double.MAX_VALUE, Double.MAX_VALUE);
	}

	private static void assertBounds(LmdbNativeCostVector vector, LmdbNativeCostVector.Feature feature,
			double low, double expected, double high) {
		assertBits(low, vector.low(feature));
		assertBits(expected, vector.expected(feature));
		assertBits(high, vector.high(feature));
	}

	private static void assertBits(double expected, double actual) {
		assertEquals(Double.doubleToRawLongBits(expected), Double.doubleToRawLongBits(actual));
	}
}
